/**
 * Get timers for all hero NPCs in this event
 * @summary Get event hero timers
 */
export const getListEventHeroTimersUrl = ({ guildId, eventId }: ListEventHeroTimersPathParameters,
    params: ListEventHeroTimersParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/guilds/${guildId}/events/${eventId}/timers?${stringifiedParams}` : `/guilds/${guildId}/events/${eventId}/timers`
}

